using System;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;
using University_Internship_Management_System.Models.FinalEvaluation;
using University_Internship_Management_System.Services.FinalEvaluation;

internal static partial class Program
{
    private sealed class PercentageFailureRepository : IFinalEvaluationRepository, IPercentageEvaluationRepository
    {
        internal readonly InMemoryFinalEvaluationRepository Inner;
        internal bool FailWrite, LostAck;
        internal Func<PercentageEvaluation,string,Task> Write;
        internal PercentageFailureRepository(InMemoryFinalEvaluationRepository inner) { Inner=inner; }
        public Task<RecordSnapshot<PercentageEvaluation>> GetPercentageAsync(string id) { return Inner.GetPercentageAsync(id); }
        public async Task SavePercentageAsync(PercentageEvaluation value,string version) { if(FailWrite)throw new RepositoryException("Simulated failure.");if(Write!=null)await Write(value,version);else await Inner.SavePercentageAsync(value,version);if(LostAck)throw new RepositoryException("Simulated acknowledgment loss."); }
        public Task<RecordSnapshot<CompanyFinalEvaluation>> GetCompanyAsync(string id) { return Inner.GetCompanyAsync(id); }
        public Task<RecordSnapshot<AcademicFinalEvaluation>> GetAcademicAsync(string id) { return Inner.GetAcademicAsync(id); }
        public Task<EvaluationPolicy> GetPolicyAsync(string id) { return Inner.GetPolicyAsync(id); }
        public Task<CompletionReview> GetCompletionReviewAsync(string id) { return Inner.GetCompletionReviewAsync(id); }
        public Task<CompletionDocument> GetCompletionDocumentAsync(string id,string doc) { return Inner.GetCompletionDocumentAsync(id,doc); }
        public Task CreateCompanyDraftAsync(CompanyFinalEvaluation value) { throw new NotSupportedException(); }
        public Task UpdateCompanyDraftAsync(CompanyFinalEvaluation value,string version) { throw new NotSupportedException(); }
        public Task CreateAcademicDraftAsync(AcademicFinalEvaluation value) { throw new NotSupportedException(); }
        public Task UpdateAcademicDraftAsync(AcademicFinalEvaluation value,string version) { throw new NotSupportedException(); }
    }
    private static async Task RunPercentageSecurityTests()
    {
        await Test("percentage failed write leaves Draft and revision unchanged",async()=>{var inner=ModernSeed(DecisionPolicy(),draft:true);var repo=new PercentageFailureRepository(inner){FailWrite=true};var s=await inner.GetPercentageAsync("fictional-internship");await Reject<RepositoryException>(()=>SavePercentage(PercentageFlow(repo),s.Version,90));Assert((await inner.GetPercentageAsync("fictional-internship")).Version==s.Version);});
        await Test("percentage lost acknowledgment does not report success or allow a stale retry",async()=>{var inner=ModernSeed(DecisionPolicy(),draft:true);var repo=new PercentageFailureRepository(inner){LostAck=true};var s=await inner.GetPercentageAsync("fictional-internship");await Reject<RepositoryException>(()=>SavePercentage(PercentageFlow(repo),s.Version,90));Assert((await inner.GetPercentageAsync("fictional-internship")).Value.Current.Percentage==90);await Reject<ConflictException>(()=>SavePercentage(PercentageFlow(repo),s.Version,90));});
        await Test("concurrent Draft updates have exactly one CAS winner",async()=>{var inner=ModernSeed(DecisionPolicy(),draft:true);var repo=new PercentageFailureRepository(inner);int count=0;var barrier=new TaskCompletionSource<bool>();repo.Write=async(v,e)=>{if(Interlocked.Increment(ref count)==2)barrier.SetResult(true);await barrier.Task;await inner.SavePercentageAsync(v,e);};var s=await inner.GetPercentageAsync("fictional-internship");Func<decimal,Task<bool>> attempt=async score=>{try{await SavePercentage(PercentageFlow(repo),s.Version,score);return true;}catch(ConflictException){return false;}};var winners=await Task.WhenAll(attempt(81),attempt(82));Assert(winners.Count(x=>x)==1);});
        await Test("concurrent Academic decisions have one exact-version winner",async()=>{var inner=ModernSeed(DecisionPolicy(),missingAcademic:true);var repo=new PercentageFailureRepository(inner);int count=0;var barrier=new TaskCompletionSource<bool>();repo.Write=async(v,e)=>{if(Interlocked.Increment(ref count)==2)barrier.SetResult(true);await barrier.Task;await inner.SavePercentageAsync(v,e);};var s=await inner.GetPercentageAsync("fictional-internship");Func<AcademicReviewKind,Task<bool>> attempt=async kind=>{try{await PercentageFlow(repo,true).ReviewAsync("fictional-internship",s.Version,s.Value.Current.VersionId,kind,"Fictional reason",Guid.NewGuid().ToString("N"),true);return true;}catch(ConflictException){return false;}};var winners=await Task.WhenAll(attempt(AcademicReviewKind.Approve),attempt(AcademicReviewKind.RequestRevision));Assert(winners.Count(x=>x)==1&&(await inner.GetPercentageAsync("fictional-internship")).Value.Reviews.Count==1);});
        await Test("Academic permission revocation blocks approval without an audit entry",async()=>{var repo=ModernSeed(DecisionPolicy(),missingAcademic:true);var s=await repo.GetPercentageAsync("fictional-internship");await Reject<UnauthorizedAccessException>(()=>PercentageFlow(repo,true,new PercentageAccess {Academic=false}).ReviewAsync("fictional-internship",s.Version,s.Value.Current.VersionId,AcademicReviewKind.Approve,"","request",true));Assert((await repo.GetPercentageAsync("fictional-internship")).Value.Reviews.Count==0);});
        await Test("Academic eligibility failure does not approve submitted company result",async()=>{var repo=ModernSeed(DecisionPolicy(),missingAcademic:true);var s=await repo.GetPercentageAsync("fictional-internship");await Reject<UnauthorizedAccessException>(()=>PercentageFlow(repo,true,new PercentageAccess {Eligible=false}).ReviewAsync("fictional-internship",s.Version,s.Value.Current.VersionId,AcademicReviewKind.Approve,"","request",true));});
        await Test("Company cannot invoke Academic review using its own identity",async()=>{var repo=ModernSeed(DecisionPolicy(),missingAcademic:true);var s=await repo.GetPercentageAsync("fictional-internship");await Reject<UnauthorizedAccessException>(()=>PercentageFlow(repo).ReviewAsync("fictional-internship",s.Version,s.Value.Current.VersionId,AcademicReviewKind.Approve,"","request",true));});
        await Test("Academic cannot save a Company draft through the new workflow",async()=>{var repo=ModernSeed(DecisionPolicy(),draft:true);var s=await repo.GetPercentageAsync("fictional-internship");await Reject<UnauthorizedAccessException>(()=>SavePercentage(PercentageFlow(repo,true),s.Version));});
        await Test("oversized comments and revision reasons are rejected without persistence",async()=>{var repo=ModernSeed(DecisionPolicy(),draft:true);var s=await repo.GetPercentageAsync("fictional-internship");await Reject<ArgumentException>(()=>SavePercentage(PercentageFlow(repo),s.Version,80,new string('x',3001)));repo=ModernSeed(DecisionPolicy(),missingAcademic:true);s=await repo.GetPercentageAsync("fictional-internship");await Reject<ArgumentException>(()=>PercentageFlow(repo,true).ReviewAsync("fictional-internship",s.Version,s.Value.Current.VersionId,AcademicReviewKind.RequestRevision,new string('x',3001),"request",true));});
        await Test("unknown Academic decision enum and missing decision ID cannot be persisted",async()=>{var repo=ModernSeed(DecisionPolicy(),missingAcademic:true);var s=await repo.GetPercentageAsync("fictional-internship");await Reject<ArgumentException>(()=>PercentageFlow(repo,true).ReviewAsync("fictional-internship",s.Version,s.Value.Current.VersionId,(AcademicReviewKind)99,"","request",true));await Reject<ArgumentException>(()=>PercentageFlow(repo,true).ReviewAsync("fictional-internship",s.Version,s.Value.Current.VersionId,AcademicReviewKind.Approve,"","",true));});
        await Test("all Firebase legacy score writers reject before any HTTP request",async()=>{var rest=Rest(new Handler{Respond=r=>throw new Exception("No request is permitted")});await Reject<NotSupportedException>(()=>rest.CreateAcademicDraftAsync(CompleteAcademicDraft()));await Reject<NotSupportedException>(()=>rest.UpdateAcademicDraftAsync(CompleteAcademicDraft(),"old"));await Reject<NotSupportedException>(()=>rest.SubmitAcademicAsync(CompleteAcademicDraft(),"old"));await Reject<NotSupportedException>(()=>rest.CreateCompanyDraftAsync(Draft()));await Reject<NotSupportedException>(()=>rest.UpdateCompanyDraftAsync(Draft(),"old"));await Reject<NotSupportedException>(()=>rest.SubmitCompanyAsync(Draft(),"old"));});
        foreach(var status in new[]{HttpStatusCode.PreconditionFailed,HttpStatusCode.ServiceUnavailable})
            await Test("Firebase percentage PUT failure is not acknowledged "+status,async()=>{var rest=Rest(new Handler{Respond=r=>r.Method==HttpMethod.Put?new HttpResponseMessage(status):Response("null","null_etag")});if(status==HttpStatusCode.PreconditionFailed)await Reject<ConflictException>(()=>rest.SavePercentageAsync(ModernValue(false,false),"null_etag"));else await Reject<RepositoryException>(()=>rest.SavePercentageAsync(ModernValue(false,false),"null_etag"));});
        await Test("Firebase percentage reader rejects a missing required schema contract",async()=>{var rest=Rest(new Handler{Respond=r=>Response("{}")});await Reject<RepositoryException>(()=>rest.GetPercentageAsync("fictional-internship"));});
        await Test("Firebase percentage reader rejects mismatched internship identity",async()=>{var rest=Rest(new Handler{Respond=r=>Response(JsonConvert.SerializeObject(ModernValue()))});await Reject<RepositoryException>(()=>rest.GetPercentageAsync("another-internship"));});
        await Test("legacy score record values remain unchanged during review denial",async()=>{var old=CompleteAcademicDraft();var repo=new InMemoryFinalEvaluationRepository(academics:new[]{old});var before=JsonConvert.SerializeObject((await repo.GetAcademicAsync(old.InternshipId)).Value);await Reject<ArgumentException>(()=>PercentageFlow(repo,true).LoadAsync(old.InternshipId,true));Assert(JsonConvert.SerializeObject((await repo.GetAcademicAsync(old.InternshipId)).Value)==before);});
        foreach(bool? disclosure in new bool?[]{null,false,true})
            await Test("Student final outcome disclosure policy "+disclosure,async()=>{var p=DecisionPolicy();p.StudentFinalOutcomeDisclosureAllowed=disclosure;var repo=ModernSeed(p);var f=new ReportFixture {Repo=repo,Metadata=new ReportMetadata(repo)};var view=await StudentFlow(f,new StudentSources()).LoadAsync("fictional-internship");Assert(view.FinalOutcome==(disclosure==true?"Pass":"Not disclosed by policy"));var json=JsonConvert.SerializeObject(view);Assert(!json.Contains("Fictional company comments")&&!json.Contains("CompanyVersionId")&&!json.Contains("AcademicSupervisorId"));});
        await Test("Student permitted outcome remains unknown when approved passing threshold is missing",async()=>{var p=DecisionPolicy();p.StudentFinalOutcomeDisclosureAllowed=true;p.PassingThreshold=null;var repo=ModernSeed(p);var view=await StudentFlow(new ReportFixture{Repo=repo,Metadata=new ReportMetadata(repo)},new StudentSources()).LoadAsync("fictional-internship");Assert(view.FinalOutcome=="Cannot yet be determined");});
        await Test("Company result does not invent a passing threshold",async()=>{var p=DecisionPolicy();p.PassingThreshold=null;var repo=ModernSeed(p);Assert((await PercentageFlow(repo).OutcomeAsync("fictional-internship")).StartsWith("Cannot yet be determined"));});
        await Test("current Academic Request Revision blocks completion even with a high percentage",async()=>{var repo=ModernSeed(DecisionPolicy(),missingAcademic:true);await ReviewPercentage(repo,AcademicReviewKind.RequestRevision,"Fictional reason");await Reject<ArgumentException>(()=>DecisionFlow(repo).DecideAsync(DecisionRequest()));});
    }
}
